import{_ as e,c as i,o as l,ah as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"焦氏易林","description":"焦氏易林，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"articles/yilin/index.md","filePath":"articles/yilin/index.md"}'),t={name:"articles/yilin/index.md"};function n(o,a,s,p,d,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="焦氏易林" tabindex="-1">焦氏易林 <a class="header-anchor" href="#焦氏易林" aria-label="Permalink to “焦氏易林”">​</a></h1><p>《焦氏易林》又稱《易林》，傳為西漢易學家 <strong>焦延壽（字贛）</strong> 所作的詩體佔書（作者歸屬亦有不同說法）。 它以《周易》六十四卦為基礎，將「本卦 → 之卦」的組合系統化：<strong>每一卦各衍生六十四卦</strong>，合成 <strong>64×64＝4096</strong> 條佔辭， 多用<strong>四言韻語</strong>呈現，把抽象卦象轉寫成更具畫面感的意象與情境。</p><h2 id="與《周易》的故事線" tabindex="-1">與《周易》的故事線 <a class="header-anchor" href="#與《周易》的故事線" aria-label="Permalink to “與《周易》的故事線”">​</a></h2><p>《周易》重在卦象與卦爻辭的義理結構；而《易林》則像是一套「把卦意變成可讀的詩句」的占筮語料庫：</p><ul><li>以詩句補足卦象的情境（人事、物象、吉凶、得失）</li><li>讓佔斷更容易抓住「象」與「機」</li><li>也成為後世象數易學與占筮實作的重要材料之一</li></ul><h2 id="本-app-如何使用《易林》" tabindex="-1">本 App 如何使用《易林》 <a class="header-anchor" href="#本-app-如何使用《易林》" aria-label="Permalink to “本 App 如何使用《易林》”">​</a></h2><p>本 App 會依你佔得的「本卦 → 之卦」自動顯示對應詩句，用來輔助解讀：</p><ol><li>先抓詩中的關鍵意象（人物、動作、地點、器物、吉凶詞）</li><li>再對照你的問題脈絡與當下處境</li><li>最後回到《周易》卦象與動爻，做整體判斷</li></ol><h2 id="翻譯說明" tabindex="-1">翻譯說明 <a class="header-anchor" href="#翻譯說明" aria-label="Permalink to “翻譯說明”">​</a></h2><p>英文詩句為中文整理翻譯而來，偏直譯；中文仍應作為主要依據，英文僅供參考。</p><ul><li>讀法：先觀詩中關鍵意象，再結合當事問題、卦象與動爻綜合判讀。</li><li>來源說明：英文翻譯從中文本《焦氏易林》整理翻譯而來，詩句以直譯為主，難以完全傳達中文之準確含義；以中文為準，英文僅供參考。</li></ul>',11)])])}const m=e(t,[["render",n]]);export{_ as __pageData,m as default};
